function feePublish(){return shell(`${pageHead('ตรวจสอบและประกาศกำหนดการ','รอบกุมภาพันธ์ 2570')}<div class="grid grid-2"><section class="card"><h3>ข้อมูลรอบ</h3><table class="table"><tr><th>วันที่</th><td>15 กุมภาพันธ์ 2570</td></tr><tr><th>พื้นที่</th><td>หมู่ที่ 6</td></tr><tr><th>ผู้รับแจ้ง</th><td>98 ครัวเรือน</td></tr></table></section><section class="card"><h3>ตัวอย่างป๊อปอัปประชาชน</h3><div class="notice"><strong>แจ้งกำหนดการจัดเก็บค่าธรรมเนียมขยะ</strong><br>เจ้าหน้าที่จะเข้าจัดเก็บวันที่ 15 กุมภาพันธ์ 2570 ณ หมู่ที่ 6 กรุณาเตรียมความพร้อม</div></section></div><div class="actions" style="justify-content:flex-end;margin-top:18px"><button class="btn btn-outline" onclick="go('fee-create')">แก้ไข</button><button class="btn btn-primary" onclick="toast('ประกาศกำหนดการแล้ว');go('fee-rounds')">ยืนยันประกาศ</button></div>`)}
function feeCalendar(){return shell(`${pageHead('ปฏิทินกำหนดการ','มกราคม 2570')}<div class="card"><div class="grid grid-4">${Array.from({length:28},(_,i)=>`<div class="card" style="min-height:92px;padding:12px"><strong>${i+1}</strong>${i===14?'<div class="badge green" style="margin-top:8px">หมู่ 5 • 120 หลัง</div>':''}${i===21?'<div class="badge amber" style="margin-top:8px">นัดหมายใหม่</div>':''}</div>`).join('')}</div></div>`)}
